package io.github.isidorotrevino.planner.postgres;
import org.junit.jupiter.api.*;
import java.sql.*;
import java.util.*;
import static org.junit.jupiter.api.Assertions.*;
import static io.github.isidorotrevino.planner.postgres.DeliveryStoreTest.*;
/** Owner proofs test SQL authority only; real signatures and stop require Compose. */
class AbsenceStoreTest {
 RecoveryStoreTest r;MultiCheckpointStoreTest m;DeliveryStoreTest f;
 @BeforeEach void setup(TestInfo info)throws Exception{r=new RecoveryStoreTest();r.setup(info);m=r.m;f=r.f;String before;try(var c=f.owner()){before=m.state(c);}assertEquals(1,migrations(f.db,"27").migrate().migrationsExecuted);migrations(f.db,"27").validate();assertEquals(0,migrations(f.db,"27").migrate().migrationsExecuted);try(var c=f.owner()){assertEquals(before,m.state(c));}}
 @AfterEach void cleanup()throws Exception{if(r!=null)r.cleanup();}
 String proof(boolean absent)throws Exception{try(var c=f.owner()){return value(c,"SELECT (i||jsonb_build_object('schema',?,'process_stopped',true,'artifact_valid',true,'receiver_closed',true,'host_observation_hash',repeat('a',64),'stdout_hash',repeat('b',64),'stderr_hash',repeat('c',64),'close_sequence',10,'receipts',rr,'receiver_seal',jsonb_build_object('receiverId',?::uuid,'sequence',10,'steps',rr,'identity',jsonb_build_object('operation',i->'operation','attempt',i->'attempt','worker',i->'worker','resource',i->'resource','generation',i->'generation'))))::text FROM (SELECT i,jsonb_object_agg(s->>'id',jsonb_build_object('status',?,'generation',i->'generation','closed',true,'payloadHash',CASE WHEN ? THEN 'null'::jsonb ELSE s->'effect_hash' END)) rr FROM (SELECT d4.recovery_info(?) i) z CROSS JOIN LATERAL jsonb_array_elements(i->'recovery_manifest'->'steps') s WHERE NOT jsonb_exists(coalesce(i->'parent_evaluation'->'applied','{}'),s->>'id') GROUP BY i) z",absent?"d4.absence.proof.v1":"d4.recovery.proof.v1",r.receiver,absent?"ABSENT":"APPLIED",absent,m.delivery);}}
 UUID record()throws Exception{var pid=id();try(var c=f.owner()){value(c,"SELECT d4.absence_record(?,?,?::jsonb)::text",pid,m.delivery,proof(true));}return pid;}
 UUID settle()throws Exception{var pid=record();var sid=id();try(var c=f.owner()){m.call(c,"absence_settle",sid,pid,m.version(c));}return sid;}
 void next(UUID seal)throws Exception{try(var c=f.owner()){m.call(c,"absence_authorize",id(),seal,m.version(c),"Explicit same-operation retry");replan(c);}m.generation++;m.launch();try(var c=f.owner()){m.call(c,"lab_authorize",id(),f.worker,m.delivery,r.receiver);}r.delivery=m.delivery;}
 void replan(Connection c)throws Exception{var store=new AbsencePlanningStore();store.observeEligibility(c,id());var capture=store.capture(c,id());var result=new io.github.isidorotrevino.planner.scheduler.CapacityScheduler().plan(capture.request(),capture.snapshot());f.plan=store.publish(c,id(),id(),capture,result);}
 void terminal()throws Exception{r.expire();try(var c=f.owner()){var pid=id();value(c,"SELECT d4.recovery_record(?,?,?::jsonb)::text",pid,m.delivery,proof(false));var sid=id();m.call(c,"recovery_settle",sid,pid,m.version(c));m.call(c,"recovery_accept",id(),sid);}}
 @Test void noProgressRetriesSameReservationThenTerminalWithTwoAccounts()throws Exception{r.receipt("step-1","UNKNOWN");r.expire();var seal=settle();m.balance("0","0","0","0");try(var c=f.owner()){assertEquals("RETRY_PENDING",value(c,"SELECT state FROM operations"));assertEquals("0",value(c,"SELECT count(*) FROM d4.multi_checkpoints"));assertEquals("0",value(c,"SELECT count(*) FROM operation_leases"));assertEquals("0",value(c,"SELECT count(*) FROM d2.commands WHERE request->>'action'='CONSUME'"));assertEquals("true",value(c,"SELECT d4.worker_execution_status(?,?)->>'retirable'",f.worker,m.delivery));}next(seal);m.balance("10","0","6","0");terminal();m.balance("0","10","0","6");try(var c=f.owner()){assertEquals("COMPLETED",value(c,"SELECT state FROM operations"));assertEquals("2/1/1",value(c,"SELECT (SELECT count(*) FROM execution_attempts)||'/'||(SELECT count(*) FROM d2.reservations)||'/'||(SELECT count(*) FROM d4.absence_links)"));assertEquals("1",value(c,"SELECT count(*) FROM d2.effect_receipts WHERE status='UNKNOWN'"));}}
 @Test void absenceAfterPrefixPreservesConsumptionAndParentLineage()throws Exception{var cp=m.commit();m.next(cp);r.delivery=m.delivery;try(var c=f.owner()){m.call(c,"lab_authorize",id(),f.worker,m.delivery,r.receiver);}r.expire();var seal=settle();m.balance("0","4","0","1");next(seal);m.balance("10","4","6","1");terminal();m.balance("0","10","0","6");try(var c=f.owner()){assertEquals("3",value(c,"SELECT count(*) FROM execution_attempts"));assertEquals("1",value(c,"SELECT count(*) FROM d4.multi_checkpoints"));}}
 @Test void liveCheckpointAfterAbsentFirstAttemptHasVerifiedLineage()throws Exception{r.expire();var seal=settle();next(seal);try(var c=f.owner()){var rid=id();m.call(c,"multi_request",rid,m.delivery,m.version(c));var p=value(c,"SELECT jsonb_set(?::jsonb,'{receipts}',(SELECT jsonb_object_agg(key,CASE WHEN key='step-1' THEN value ELSE jsonb_set(value,'{status}','\"ABSENT\"') END) FROM jsonb_each(?::jsonb->'receipts')))::text",proof(false),proof(false));var pid=id();value(c,"SELECT d4.multi_record_proof(?,?,?,?::jsonb)::text",pid,m.delivery,rid,p.replace("d4.recovery.proof.v1","d4.checkpoint.proof.v2"));m.call(c,"multi_commit",id(),rid,pid,m.version(c));assertEquals("CANCELLED",value(c,"SELECT state FROM operations"));}m.balance("0","4","0","1");}
 @Test void unknownClosedFalseWrongHashAndMissingStopCannotMintAbsence()throws Exception{r.expire();try(var c=f.owner()){var p=proof(true);for(var expr:List.of("jsonb_set(?::jsonb,'{receipts,step-1,status}','\"UNKNOWN\"')","jsonb_set(?::jsonb,'{receipts,step-1,closed}','false')","jsonb_set(?::jsonb,'{process_stopped}','false')","?::jsonb-'host_observation_hash'","jsonb_set(?::jsonb,'{recovery_manifest_hash}','\"wrong\"')")){var bad=value(c,"SELECT ("+expr+")::text",p);m.reject("23514",()->value(c,"SELECT d4.absence_record(?,?,?::jsonb)::text",id(),m.delivery,bad));}}m.balance("10","0","6","0");}
 @Test void appliedFactCannotBeDeclaredAbsent()throws Exception{r.receipt("step-1","APPLIED");r.expire();m.reject("23514",()->record());m.balance("10","0","6","0");}
 @Test void liveLeaseCannotUseAbsence()throws Exception{m.reject("23514",()->record());m.balance("10","0","6","0");}
 @Test void newFactBetweenIngressAndSettlementRetainsEveryCommitment()throws Exception{r.expire();var pid=record();r.receipt("step-2","UNKNOWN");try(var c=f.owner()){m.reject("23514",()->m.call(c,"absence_settle",id(),pid,m.version(c)));assertEquals("1",value(c,"SELECT count(*) FROM operation_leases"));assertEquals("0",value(c,"SELECT count(*) FROM d4.absence_seals"));}m.balance("10","0","6","0");}
 @Test void newFactAfterSettlementInvalidatesAuthorization()throws Exception{r.expire();var seal=settle();r.receipt("step-2","UNKNOWN");try(var c=f.owner()){m.reject("23514",()->m.call(c,"absence_authorize",id(),seal,m.version(c),"stale proof"));assertEquals("RETRY_PENDING",value(c,"SELECT state FROM operations"));}}
 @Test void replayDoesNotReleaseOrConsumeAgainAndChangedCommandConflicts()throws Exception{r.expire();var pid=record();try(var c=f.owner()){var cid=id();long v=m.version(c);var result=m.call(c,"absence_settle",cid,pid,v);var journal=value(c,"SELECT jsonb_agg(to_jsonb(j) ORDER BY id)::text FROM d2.journal j");assertEquals(result,m.call(c,"absence_settle",cid,pid,v));assertEquals(journal,value(c,"SELECT jsonb_agg(to_jsonb(j) ORDER BY id)::text FROM d2.journal j"));m.reject("23514",()->m.call(c,"absence_settle",cid,pid,v+1));}}
 @Test void changedVersionAndOrdinaryRetryCannotBorrowAbsenceAuthority()throws Exception{r.expire();var seal=settle();try(var c=f.owner()){m.reject("23514",()->m.call(c,"absence_authorize",id(),seal,m.version(c)+1,"stale version"));sql(c,"UPDATE operations SET state='READY',row_version=row_version+1");assertEquals("false",value(c,"SELECT d4.continuation_safe(?,1)::text",f.operation));assertThrows(SQLException.class,()->m.launch());assertEquals("1",value(c,"SELECT count(*) FROM execution_attempts"));}}
 @Test void exhaustedAttemptBudgetRetainsCommitments()throws Exception{r.expire();try(var c=f.owner()){sql(c,"UPDATE operations SET policy_snapshot=policy_snapshot||'{\"max_attempts\":1}'::jsonb");m.reject("23514",()->record());}m.balance("10","0","6","0");}
 @Test void factsAreImmutableAndRuntimeCannotCreateOrAuthorizeSeal()throws Exception{r.expire();settle();try(var c=f.owner()){for(var table:List.of("absence_seals","absence_authorizations","absence_links"))m.reject("55000",()->sql(c,"UPDATE d4."+table+" SET "+(table.equals("absence_links")?"generation=generation":table.equals("absence_seals")?"generation=generation":"reason=reason")));sql(c,"CREATE ROLE absence_runtime NOLOGIN;GRANT USAGE ON SCHEMA d4 TO absence_runtime;SET ROLE absence_runtime");m.reject("42501",()->value(c,"SELECT d4.absence_record(NULL,NULL,'{}')::text"));m.reject("42501",()->value(c,"SELECT d4.absence_authorize(NULL,NULL,0,'x')::text"));m.reject("42501",()->sql(c,"SELECT * FROM d4.absence_seals"));}}
 @Test void newAbsenceAuthorizationInvalidatesPublishedCapture()throws Exception{r.expire();var seal=settle();try(var c=f.owner()){m.call(c,"absence_authorize",id(),seal,m.version(c),"first");replan(c);m.call(c,"absence_authorize",id(),seal,m.version(c),"new authority");assertThrows(SQLException.class,()->m.launch());assertEquals("1",value(c,"SELECT count(*) FROM execution_attempts"));}}
 @Test void settlementCannotUseRecoveryProofEntrypoint()throws Exception{r.expire();var pid=r.record(false);try(var c=f.owner()){m.reject("23514",()->m.call(c,"absence_settle",id(),pid,m.version(c)));}m.balance("10","0","6","0");}
 @Test void missingLeaseAfterProofDoesNotReleaseCapacity()throws Exception{r.expire();var pid=record();try(var c=f.owner()){sql(c,"DELETE FROM operation_leases");m.reject("23514",()->m.call(c,"absence_settle",id(),pid,m.version(c)));assertEquals("0",value(c,"SELECT count(*) FROM d4.absence_seals"));}m.balance("10","0","6","0");}
 @Test void oldCallbackIsFencedAfterAbsentRetry()throws Exception{var old=m.delivery;r.expire();var seal=settle();next(seal);try(var c=f.owner()){m.reject("23514",()->f.call(c,"worker_execution",id(),f.worker,Map.of("action","CALLBACK","delivery_id",old,"payload",Map.of("entries",List.of()))));assertEquals("2",value(c,"SELECT lease_generation FROM operations"));}m.balance("10","0","6","0");}
 @Test void secondAccountDeficitCannotPartiallyTopUpAfterAbsence()throws Exception{r.expire();var seal=settle();try(var c=f.owner()){m.call(c,"absence_authorize",id(),seal,m.version(c),"Explicit retry");replan(c);value(c,"SELECT d2.recalibrate(?,?::jsonb)::text",id(),Json.write(Map.of("account_id",m.b,"capacity",8,"confidence",1,"evidence_sha256","d".repeat(64),"reason","Synthetic reduced physical quota")));assertThrows(SQLException.class,()->m.launch());assertEquals("1",value(c,"SELECT count(*) FROM execution_attempts"));assertEquals("0",value(c,"SELECT count(*) FROM d4.absence_links"));}m.balance("0","0","0","0");}
 @Test void repeatedAbsenceUsesThirdAttemptWithoutResettingBudget()throws Exception{r.expire();next(settle());r.expire();next(settle());try(var c=f.owner()){assertEquals("3",value(c,"SELECT count(*) FROM execution_attempts"));assertEquals("2",value(c,"SELECT count(*) FROM d4.absence_links"));}r.expire();m.reject("23514",()->record());m.balance("10","0","6","0");}
 @Test void newSealAfterCaptureInvalidatesPublication()throws Exception{r.expire();var seal=settle();try(var c=f.owner()){m.call(c,"absence_authorize",id(),seal,m.version(c),"first authority");var store=new AbsencePlanningStore();store.observeEligibility(c,id());var capture=store.capture(c,id());var result=new io.github.isidorotrevino.planner.scheduler.CapacityScheduler().plan(capture.request(),capture.snapshot());m.call(c,"absence_authorize",id(),seal,m.version(c),"replacement authority");m.reject("40001",()->store.publish(c,id(),id(),capture,result));}}

}
